-- Production resources and route stages (SAP B1 Resources module and Route
-- Stages setup), BOM / production order stages, and resource rows on issues.

-- SDK ORSB / ORSC: resource groups and resource master data. StdCost is the
-- resource's standard cost per unit; ResAcct is credited when a resource is
-- issued to production (resource absorption), WIP is debited.
CREATE TABLE IF NOT EXISTS "ORSB" (
  "ResGrpCod" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "ResGrpNam" TEXT NOT NULL,
  "ResType" CHAR(1) DEFAULT 'M'
);
CREATE UNIQUE INDEX IF NOT EXISTS "ORSB_name_unique" ON "ORSB" (lower("ResGrpNam"));
ALTER TABLE "ORSC"
  ADD COLUMN IF NOT EXISTS "ResType" CHAR(1) DEFAULT 'M',
  ADD COLUMN IF NOT EXISTS "ResGrpCod" INTEGER REFERENCES "ORSB"("ResGrpCod"),
  ADD COLUMN IF NOT EXISTS "UnitOfMsr" TEXT,
  ADD COLUMN IF NOT EXISTS "IssueMthd" CHAR(1) DEFAULT 'M',
  ADD COLUMN IF NOT EXISTS "StdCost" NUMERIC(19,6) DEFAULT 0,
  ADD COLUMN IF NOT EXISTS "ResAcct" TEXT REFERENCES "OACT"("AcctCode"),
  ADD COLUMN IF NOT EXISTS "validFor" CHAR(1) DEFAULT 'Y',
  ADD COLUMN IF NOT EXISTS "FrgnName" TEXT,
  ADD COLUMN IF NOT EXISTS "Remarks" TEXT;

-- SDK ORST: route stages.
CREATE TABLE IF NOT EXISTS "ORST" (
  "AbsEntry" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Code" TEXT NOT NULL, "Desc" TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS "ORST_code_unique" ON "ORST" (lower("Code"));

-- SDK ITT2 / WOR4: the route stages of a BOM and of a production order; rows
-- point at a stage through StageId.
CREATE TABLE IF NOT EXISTS "ITT2" (
  "Father" TEXT NOT NULL REFERENCES "OITT"("Code"), "StageId" INTEGER NOT NULL, "SeqNum" INTEGER,
  "StgEntry" INTEGER REFERENCES "ORST"("AbsEntry"), "Name" TEXT, PRIMARY KEY ("Father", "StageId")
);
CREATE TABLE IF NOT EXISTS "WOR4" (
  "DocEntry" INTEGER NOT NULL REFERENCES "OWOR"("DocEntry"), "StageId" INTEGER NOT NULL, "SeqNum" INTEGER,
  "StgEntry" INTEGER REFERENCES "ORST"("AbsEntry"), "Name" TEXT, "StartDate" DATE, "EndDate" DATE,
  PRIMARY KEY ("DocEntry", "StageId")
);

-- Issue rows keep their type (4 item, 290 resource). A resource row carries the
-- resource code, so the item foreign key goes (the engine checks item rows itself).
ALTER TABLE "IGE1" ADD COLUMN IF NOT EXISTS "ItemType" INTEGER DEFAULT 4;
ALTER TABLE "IGE1" DROP CONSTRAINT IF EXISTS "IGE1_ItemCode_fkey";

-- G/L Account Determination fallback for resources without their own account.
ALTER TABLE "OACP" ADD COLUMN IF NOT EXISTS "ResAcct" TEXT REFERENCES "OACT"("AcctCode");
DO $$
DECLARE code TEXT;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "OACT" WHERE "AcctCode" = '120000') THEN RETURN; END IF;
  SELECT "AcctCode" INTO code FROM "OACT" WHERE "AcctName" = 'Resource Absorption' ORDER BY "AcctCode" LIMIT 1;
  IF code IS NULL THEN
    SELECT u.c INTO code FROM unnest(ARRAY['540000', '545000', '549000', '591000']) WITH ORDINALITY AS u(c, n)
      WHERE NOT EXISTS (SELECT 1 FROM "OACT" WHERE "AcctCode" = u.c) ORDER BY u.n LIMIT 1;
    IF code IS NOT NULL THEN
      INSERT INTO "OACT" ("AcctCode", "AcctName", "GroupMask", "FormatCode") VALUES (code, 'Resource Absorption', 5, code);
    END IF;
  END IF;
  IF code IS NOT NULL THEN UPDATE "OACP" SET "ResAcct" = COALESCE("ResAcct", code); END IF;
END $$;
